const BOOKINGS_STORAGE_KEY="buildskil_bookings_v2",BOOKED_USERS_STORAGE_KEY="buildskil_booked_users_v1",MY_ADDRESS_STORAGE_KEY="buildskil_my_address_v1",MY_ADDRESSES_STORAGE_KEY="buildskil_my_addresses_v2",LOGIN_USER_STORAGE_KEY="cb_login_user",EMPTY_ADDRESS={id:"",name:"",houseFlat:"",streetArea:"",landmark:"",townCityVillage:"",district:"",state:"",pincode:"",country:"India",latitude:"",longitude:"",addressType:"Work"};function readJson(t,e){try{const n=localStorage.getItem(t);return n?JSON.parse(n):e}catch{return e}}function writeJson(t,e){localStorage.setItem(t,JSON.stringify(e))}function uid(t){return`${t}_${Date.now()}_${Math.random().toString(36).slice(2,8)}`}function formatFullAddress(t){return t?[t.houseFlat,t.streetArea,t.landmark,t.townCityVillage,t.district,t.state,t.pincode,t.country].filter(Boolean).join(", "):""}function hasUsableAddress(t){return!!t&&!![t.houseFlat,t.streetArea,t.townCityVillage,t.district].some(e=>String(e||"").trim())}function readBookings(){const t=readJson(BOOKINGS_STORAGE_KEY,[]);return Array.isArray(t)?t:[]}function writeBookings(t){writeJson(BOOKINGS_STORAGE_KEY,t)}function readLoginUser(){const t=readJson(LOGIN_USER_STORAGE_KEY,{});return{id:String(t?.id||t?._id||t?.userId||""),name:String(t?.name||t?.fullName||"BuildSkil User"),phone:String(t?.phone||t?.mobile||""),email:t?.email?String(t.email):""}}function readMyAddresses(){let t=readJson(MY_ADDRESSES_STORAGE_KEY,null);if(Array.isArray(t))return t.map((n,i)=>({...EMPTY_ADDRESS,...n,id:String(n?.id||uid("address"))}));const e=readJson(MY_ADDRESS_STORAGE_KEY,null);return e?[{...EMPTY_ADDRESS,...e,id:String(e?.id||uid("address"))}]:[]}function readMyAddress(){return readMyAddresses()[0]||null}function writeMyAddresses(t){writeJson(MY_ADDRESSES_STORAGE_KEY,t),t[0]?writeJson(MY_ADDRESS_STORAGE_KEY,t[0]):localStorage.removeItem(MY_ADDRESS_STORAGE_KEY)}function saveLegacyBookedUser(t,e){const n=readJson(BOOKED_USERS_STORAGE_KEY,[]),r=(Array.isArray(n)?n:[]).filter(o=>String(o?.profile?.id)!==String(t.id));r.unshift({profile:t,bookedAt:e}),writeJson(BOOKED_USERS_STORAGE_KEY,r)}function getProfileSession(){return readJson("buildskil_book_profile_v1",null)}function setProfileSession(t){writeJson("buildskil_book_profile_v1",t)}function setReadonlyAddress(t){writeJson("buildskil_readonly_address_v1",t)}function getReadonlyAddress(){return readJson("buildskil_readonly_address_v1",null)}function escapeHtml(t){return String(t??"").replace(/&/g,"&amp;").replace(/</g,"&lt;").replace(/>/g,"&gt;").replace(/"/g,"&quot;").replace(/'/g,"&#039;")}function formatDateTime(t){return t?new Date(t).toLocaleString("en-IN",{day:"2-digit",month:"short",year:"numeric",hour:"2-digit",minute:"2-digit"}):""}function callPhone(t){const e=String(t||"").trim().replace(/[^0-9+]/g,"");e&&(location.href=`tel:${e}`)}
